# Build save_v3.mjs. Harness fix: witness boot E and M, and only real saves.
# Do not edit this file after it runs.
from pathlib import Path

text = Path('work/scripts/save_v2.mjs').read_text(encoding='utf-8')
text = text.replace('save-v2', 'save-v3').replace('save_v2', 'save_v3')
text = text.replace('save-table-v2.json', 'save-table-v3.json')
text = text.replace(
    'Correction experiment 2. Harness fix for the stale baseline k1dd1 literal.',
    'Correction experiment 3. Witness boot E and M as well as the menu M. Restore finish after each NAND call.',
)
old = "function watchSaves(ctx) {"
start = text.find(old)
end = text.find("function decodeStore(file) {")
if start < 0 or end < 0:
    raise SystemExit(f'markers {start} {end}')
witness = r'''const holder = { events: [] };

async function installWitness() {
  process.env.OM_EMU_MODEL = 'E147';
  const menu = await import(pathToFileURL(resolve(checkout, 'emu/src/lab/menu.mjs')).href);
  const proto = menu.MenuLab.prototype;
  if (proto.__saveWitness) return;
  const orig = proto._s_nand_write;
  proto._s_nand_write = function(hle, r, posted) {
    const before = this.store_log && this.store_log.nvram ? this.store_log.nvram.saves.length : 0;
    const origAfter = hle.finish_after.bind(hle);
    const origFinish = hle.finish.bind(hle);
    let captured = null;
    hle.finish_after = (regs, fn, args) => {
      captured = { via: 'callback', intended: args.d0 >>> 0, callback: fn >>> 0 };
      this.observe(fn, (lab, rr) => {
        const status = rr.d0 >>> 0;
        const pending = holder.events.findLast((ev) => ev.via === 'callback' && ev.status === null);
        if (pending) pending.status = status;
        else holder.events.push({ when: 'callback-entry', status, posted: true });
      }, 'obs-save-cb-' + (fn >>> 0).toString(16));
      return origAfter(regs, fn, args);
    };
    hle.finish = (regs, args = {}) => {
      captured = { via: 'return', status: (args.d0 ?? 0) >>> 0 };
      return origFinish(regs, args);
    };
    try {
      return orig.call(this, hle, r, posted);
    } finally {
      hle.finish_after = origAfter;
      hle.finish = origFinish;
      const saves = this.store_log && this.store_log.nvram ? this.store_log.nvram.saves : null;
      if (saves && saves.length > before && captured) {
        const rec = saves[saves.length - 1];
        holder.events.push({
          store: rec.store,
          from: rec.from,
          posted: !!rec.posted,
          via: captured.via,
          intended: captured.intended !== undefined ? captured.intended : captured.status,
          status: captured.via === 'return' ? captured.status : null,
          callback: captured.callback ?? null,
        });
      }
    }
  };
  proto.__saveWitness = true;
}

'''
text = text[:start] + witness + text[end:]
old_check = '''      const before = ctx.l.store_log.nvram.saves.length;
      let previous = null;'''
new_check = '''      let previous = null;'''
if old_check not in text:
    raise SystemExit('before marker missing')
text = text.replace(old_check, new_check, 1)
old_end = '''      const log = ctx.l.store_log.nvram.saves.map((rec) => ({
        store: rec.store, from: rec.from, posted: rec.posted,
      }));
      const added = log.slice(before);
      const problems = [];
      if (!added.some((rec) => rec.store === 'M')) problems.push('log-M');
      if (!added.some((rec) => rec.store === 'E')) problems.push('log-E');
      if (watch.events.length < added.length) problems.push('status-missing');
      if (watch.queue.length) problems.push('callback-pending');
      for (const ev of watch.events) {
        if (ev.status !== 0) problems.push('status');
      }
      const byStore = {};
      for (const ev of watch.events) if (ev.store) byStore[ev.store] = ev;
      if (!byStore.M || byStore.M.status !== 0) problems.push('M-status');
      if (!byStore.E || byStore.E.status !== 0) problems.push('E-status');
      emit({
        id: 'save-v3-completion',
        step: 'save',
        pass: problems.length === 0,
        problems,
        expected: { stores: ['M', 'E'], status: 0 },
        actual: { added, events: watch.events, pending: watch.queue.length, screen: ctx.s.screen() },
      });
      if (problems.length) throw new Error('save ' + problems.join(','));'''
new_end = '''      const log = ctx.l.store_log.nvram.saves.map((rec) => ({
        store: rec.store, from: rec.from, posted: rec.posted,
      }));
      const events = holder.events.map((ev) => ({ ...ev }));
      const problems = [];
      for (const name of ['M', 'E']) {
        if (!log.some((rec) => rec.store === name)) problems.push('log-' + name);
        const rows = events.filter((ev) => ev.store === name);
        if (!rows.length) problems.push('witness-' + name);
        if (rows.some((ev) => ev.status !== 0)) problems.push(name + '-status');
      }
      if (events.some((ev) => ev.status === null)) problems.push('callback-pending');
      emit({
        id: 'save-v3-completion',
        step: 'save',
        pass: problems.length === 0,
        problems,
        expected: { stores: ['M', 'E'], status: 0 },
        actual: { log, events, screen: ctx.s.screen() },
      });
      holder.events = [];
      if (problems.length) throw new Error('save ' + problems.join(','));'''
if old_end not in text:
    raise SystemExit('completion block missing')
text = text.replace(old_end, new_end, 1)
text = text.replace(
    '    async drive(ctx) {\n      const watch = await watchSaves(ctx);\n      queueRef = watch.queue;\n      witnessed.push(...watch.events);\n      const setup = await prepare(ctx);',
    '    async drive(ctx) {\n      const setup = await prepare(ctx);',
    1,
)
text = text.replace(
    'const menu = await runMenu();',
    'await installWitness();\nconst menu = await runMenu();',
    1,
)
# drop unused locals if the function still declares them
text = text.replace(
    'async function runMenu() {\n  const witnessed = [];\n  let queueRef = null;\n  const result = await runZone({',
    'async function runMenu() {\n  const result = await runZone({',
    1,
)
text = text.replace(
    '  return { result, witnessed, queueRef };',
    '  return { result };',
    1,
)
Path('work/scripts/save_v3.mjs').write_text(text, encoding='utf-8')
print('wrote', len(text))
